    @Test
    void roleTest() {
        UserMessage userMessage = new UserMessage("Tell me about 3 famous pirates from the Golden Age of Piracy and what they did.");
        SystemPromptTemplate systemPromptTemplate = new SystemPromptTemplate(this.systemResource);
        Message systemMessage = systemPromptTemplate.createMessage(Map.of("name", "Bob", "voice", "pirate"));
        Prompt prompt = new Prompt(List.of(userMessage, systemMessage));
        ChatResponse response = this.chatModel.call(prompt);
        assertThat(response.getResults()).hasSize(1);
        assertThat(response.getResults().get(0).getOutput().getText()).contains("Blackbeard");
    }

    @Test
    void streamRoleTest() {
        UserMessage userMessage = new UserMessage("Tell me about 3 famous pirates from the Golden Age of Piracy and what they did.");
        SystemPromptTemplate systemPromptTemplate = new SystemPromptTemplate(this.systemResource);
        Message systemMessage = systemPromptTemplate.createMessage(Map.of("name", "Bob", "voice", "pirate"));
        Prompt prompt = new Prompt(List.of(userMessage, systemMessage));
        Flux<ChatResponse> flux = this.chatModel.stream(prompt);
        List<ChatResponse> responses = flux.collectList().block();
        assertThat(responses.size()).isGreaterThan(1);
        String stitchedResponseContent = responses.stream().map(ChatResponse::getResults).flatMap(List::stream).map(Generation::getOutput).map(AssistantMessage::getText).collect(Collectors.joining());
        assertThat(stitchedResponseContent).contains("Blackbeard");
